initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the client at '${endpoint}' receives a valid Notification containing:
        Notification received After waiting '15' seconds
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions'
        method set to 'POST'
        Create Context Source Registration Subscription with filename set to '${subscription_payload}', accept set to '${EMPTY}', and content-type set to 'application/ld+json'
}
